function fmtDuration(seconds){const mins=Math.round((Number(seconds)||0)/60);return mins<60?`${mins} min`:`${Math.floor(mins/60)} h ${String(mins%60).padStart(2,'0')} min`}
function sessionDate(value){return new Date(`${String(value).replace(' ','T')}Z`)}
function localDateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function completedWorkoutDaysForToday(rows,now=new Date()){const key=localDateKey(now);return new Set(rows.filter(row=>row.workout_day_id&&localDateKey(sessionDate(row.completed_at))===key).map(row=>Number(row.workout_day_id)))}
function completedWorkoutSessionsForToday(rows,now=new Date()){const key=localDateKey(now);return rows.filter(row=>row.workout_day_id&&localDateKey(sessionDate(row.completed_at))===key)}
function updatePlannerStartButtons(){document.querySelectorAll('[data-start-weekday]').forEach(button=>{const weekday=Number(button.dataset.startWeekday),day=activePlan?.days.find(item=>item.weekday===weekday),completed=day&&completedWorkoutDayIdsToday.has(day.id),canResume=executionPaused&&executionWeekday===weekday;button.disabled=false;button.textContent=canResume?'Retomar treino':completed?'Outra sessão hoje':'Iniciar treino'})}
function sessionDay(row){return sessionDate(row.completed_at).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'})}
function activeStreak(rows){const dates=new Set(rows.map(row=>{const d=sessionDate(row.completed_at);return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`}));if(!dates.size)return 0;const cursor=new Date();cursor.setUTCHours(0,0,0,0);let key=cursor.toISOString().slice(0,10);if(!dates.has(key)){cursor.setUTCDate(cursor.getUTCDate()-1);key=cursor.toISOString().slice(0,10);if(!dates.has(key))return 0}let count=0;while(dates.has(key)){count++;cursor.setUTCDate(cursor.getUTCDate()-1);key=cursor.toISOString().slice(0,10)}return count}
function estimateWorkoutMinutes(day){const sets=(day?.exercises||[]).flatMap(ex=>ex.sets||[]);if(!sets.length)return null;const activeSeconds=sets.length*45,restSeconds=sets.slice(0,-1).reduce((n,set)=>n+Math.max(0,Number(set.rest_seconds)||0),0);return Math.max(5,Math.round((activeSeconds+restSeconds)/300)*5)}
function workoutSummary(day){const exercises=day?.exercises||[],sets=exercises.reduce((n,ex)=>n+(ex.sets||[]).length,0),parts=[`${exercises.length} ${exercises.length===1?'exercício':'exercícios'}`,`${sets} ${sets===1?'série':'séries'}`],minutes=estimateWorkoutMinutes(day);if(minutes!==null)parts.push(`~${minutes} min`);return parts.join(' · ')}
function nextExpandedPlannerDay(activeWeekday,actionWeekday,action){return action==='close'?null:actionWeekday}
