function buildSetPatchPayload(values){return {repetitions:values.repetitions===''?null:Number(values.repetitions),load_value:values.load_value===''?null:Number(values.load_value),load_unit:values.load_unit,rest_seconds:values.rest_seconds===''?0:Number(values.rest_seconds),notes:values.notes||''}}
function updateActivePlanSet(updatedSet){if(!activePlan||!updatedSet)return;for(const day of activePlan.days){for(const exercise of day.exercises){const set=exercise.sets.find(candidate=>candidate.id===updatedSet.id);if(set){Object.assign(set,updatedSet);return}}}}
function dayHasWorkout(day){return Boolean(day?.exercises?.length)}
